<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ApiError } from '../../api/errors.js'
import { session } from '../../auth/session.js'
import { fetchAccessModules, fetchAccessPermissions, fetchAccessRoles, fetchDepartments, saveAccessRole } from '../../master/api.js'
import MasterPanelHeader from '../master/MasterPanelHeader.vue'

const rows = ref([]); const modules = ref([]); const permissions = ref([]); const departments = ref([]); const loading = ref(false); const saving = ref(false); const ready = ref(false); const error = ref(''); const notice = ref(''); const editing = ref(false); const editingCode = ref('')
const form = reactive({ code: '', name: '', description: '', moduleCode: '', departmentId: '', orderSort: 0, standName: '', status: 'ACTIVE', hidden: false, system: false, permissionCodes: [] })
const canSave = computed(() => ready.value && !loading.value && !saving.value)
const canEditProtected = computed(() => session.user?.developer === true)
function message(e) { return e instanceof ApiError ? e.message : '请求失败' }
async function load() {
  loading.value = true; ready.value = false; error.value = ''
  try { const [roleList, moduleList, permissionList, departmentList] = await Promise.all([fetchAccessRoles(session.accessToken), fetchAccessModules(session.accessToken), fetchAccessPermissions(session.accessToken), fetchDepartments(session.accessToken, {})]); rows.value = roleList.items || []; modules.value = moduleList.items || []; permissions.value = permissionList.items || []; departments.value = departmentList.items || []; ready.value = true }
  catch (e) { error.value = message(e) } finally { loading.value = false }
}
function create() { editing.value = true; editingCode.value = ''; Object.assign(form, { code: '', name: '', description: '', moduleCode: '', departmentId: '', orderSort: 0, standName: '', status: 'ACTIVE', hidden: false, system: false, permissionCodes: [] }); notice.value = '' }
function edit(row) {
  if ((row.system || row.hidden) && !canEditProtected.value) { notice.value = '该角色包含受保护属性，需要开发者账号维护'; return }
  editing.value = true; editingCode.value = row.code; Object.assign(form, { code: row.code, name: row.name, description: row.description || '', moduleCode: row.moduleCode || '', departmentId: row.departmentId || '', orderSort: row.orderSort ?? 0, standName: row.standName || '', status: row.status || 'ACTIVE', hidden: Boolean(row.hidden), system: Boolean(row.system), permissionCodes: [...(row.permissionCodes || [])] }); notice.value = ''
}
async function save() { if (!canSave.value) return; saving.value = true; try { await saveAccessRole(session.accessToken, editingCode.value, form); editing.value = false; notice.value = '角色已保存'; await load() } catch (e) { notice.value = message(e) } finally { saving.value = false } }
onMounted(load)
</script>

<template>
  <section class="patient-panel master-data-panel access-data-panel" aria-labelledby="access-roles-heading">
    <MasterPanelHeader title="角色与范围" title-id="access-roles-heading" icon="overview" description="角色可绑定模块、科室范围和多项权限；用户继承角色权限并集。" :count="ready ? rows.length : null" :loading="loading"><template #actions><button class="button button-compact" type="button" :disabled="!canSave" @click="create">新建角色</button></template></MasterPanelHeader>
    <form v-if="editing" class="master-form" data-testid="access-role-form" @submit.prevent="save"><div class="master-editor-head"><div><p class="master-eyebrow">ROLE DEFINITION</p><h3>{{ editingCode ? '编辑角色' : '新建角色' }}</h3></div><span class="master-soft-badge">{{ editingCode || '新记录' }}</span></div><div class="field-grid"><label class="field"><span>角色编码</span><input v-model="form.code" :disabled="Boolean(editingCode)" required /></label><label class="field"><span>角色名称</span><input v-model="form.name" required /></label><label class="field"><span>所属模块</span><select v-model="form.moduleCode"><option value="">全模块</option><option v-for="item in modules" :key="item.code" :value="item.code">{{ item.name }}（{{ item.code }}）</option></select></label><label class="field"><span>科室范围</span><select v-model="form.departmentId"><option value="">全科室</option><option v-for="department in departments.filter((item) => item.status === 'ACTIVE')" :key="department.departmentId" :value="department.departmentId">{{ department.deptName }}（{{ department.deptCode }}）</option><option v-if="form.departmentId && !departments.some((item) => item.departmentId === form.departmentId)" :value="form.departmentId" disabled>{{ form.departmentId }}（目录不存在）</option><option v-else-if="form.departmentId && departments.find((item) => item.departmentId === form.departmentId)?.status !== 'ACTIVE'" :value="form.departmentId" disabled>{{ form.departmentId }}（科室已停用）</option></select></label><label class="field"><span>排列顺序</span><input v-model.number="form.orderSort" type="number" step="1" /></label><label class="field"><span>标准岗位名称</span><input v-model="form.standName" maxlength="128" /></label><label class="field"><span>状态</span><select v-model="form.status"><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select></label><label class="field"><span>说明</span><input v-model="form.description" /></label></div><fieldset class="role-picks"><legend>权限集合</legend><label v-for="permission in permissions" :key="permission.code" class="role-pick" :class="{ 'is-selected': form.permissionCodes.includes(permission.code), 'is-disabled': permission.status !== 'ACTIVE' }"><input v-model="form.permissionCodes" type="checkbox" :value="permission.code" :disabled="form.system || permission.status !== 'ACTIVE' || saving" /><span>{{ permission.name }}（{{ permission.code }}）<small v-if="permission.status !== 'ACTIVE'">已停用</small></span></label></fieldset><div class="access-checks"><label><input v-model="form.hidden" type="checkbox" :disabled="!canEditProtected" /> 隐藏角色</label><label><input v-model="form.system" type="checkbox" :disabled="!canEditProtected" /> 系统角色</label></div><p v-if="!canEditProtected" class="access-inline-note">隐藏和系统角色属性仅由开发者维护；系统角色不能停用。</p><div class="panel-actions"><button class="button button-compact" type="submit" :disabled="!canSave">{{ saving ? '正在保存…' : '保存角色' }}</button><button class="button button-ghost button-compact" type="button" @click="editing = false">取消</button></div></form>
    <p v-if="notice" class="banner" role="status">{{ notice }}</p><p v-if="loading" class="shell-status">正在读取角色…</p><p v-else-if="error" class="banner" role="alert">{{ error }} <button class="button button-ghost button-compact" type="button" @click="load">重试</button></p><p v-else-if="ready && !rows.length" class="result-empty">暂无角色</p><div v-else-if="ready" class="result-wrap" tabindex="0"><div class="master-table-head"><h3>角色列表</h3><span>{{ rows.length }} 条</span></div><table class="register-table"><thead><tr><th>编码</th><th>名称 / 标准岗位</th><th>模块 / 科室</th><th>排序</th><th>权限数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.code"><td class="mono">{{ row.code }}</td><td class="master-primary-cell">{{ row.name }}<small>{{ row.standName || '—' }}</small></td><td>{{ row.moduleCode || '全模块' }}<span v-if="row.departmentId"> / {{ row.departmentId }}</span></td><td>{{ row.orderSort ?? 0 }}</td><td>{{ (row.permissionCodes || []).length }}</td><td><span class="status-pill" :data-status="row.status">{{ row.status === 'ACTIVE' ? '启用' : '停用' }}</span></td><td class="ticket-actions"><button class="text-btn" type="button" :disabled="!canSave || (row.system || row.hidden) && !canEditProtected" @click="edit(row)">{{ row.system || row.hidden ? '受保护角色' : '编辑' }}</button></td></tr></tbody></table></div>
    <p class="master-list-foot">系统角色由安装种子保护；删除和临床规则二次认证不在此页面执行。</p>
  </section>
</template>
